// Proportional bitmap fonts (EB Garamond Bold at a few sizes).
// Glyph data is in fonts.cpp, generated by tools/gen_font.py.
#pragma once
#include <stddef.h>
#include <stdint.h>

struct GlyphInfo {
  uint16_t offset;  // start of this glyph's bitmap in Font::bits
  uint8_t advance;  // pixels to move right after drawing it
  int8_t xoff;      // bitmap's left edge relative to the pen position (can be negative)
  uint8_t w;        // bitmap width in pixels (0 for a space)
};

struct Font {
  uint8_t h;       // cell height = bitmap rows per glyph
  uint8_t ascent;  // baseline is `ascent` rows below the cell top
  const GlyphInfo *info;  // 95 glyphs (ASCII 32..126)
  const uint8_t *bits;    // per glyph: h rows of ceil(w / 8) bytes, MSB first, 1 = ink

  // Anything outside 32..126 shows as '?'.
  const GlyphInfo &glyph(char c) const {
    int i = (c < 32 || c > 126) ? ('?' - 32) : (c - 32);
    return info[i];
  }
  int advance(char c) const { return glyph(c).advance; }
};

extern const Font FONT_20, FONT_22, FONT_30, FONT_32, FONT_36;
